begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(16);
set local role authenticated;
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000001', true);
select is(jsonb_array_length(teacher_workspace_read('aaaaaaaa-0000-0000-0000-000000000001')->'data'->'classes'), 2, 'reads the complete own-school snapshot');
select is(teacher_workspace_read('bbbbbbbb-0000-0000-0000-000000000001'), null::jsonb, 'cannot read another school');
select set_config('test.workspace_version', teacher_workspace_read('aaaaaaaa-0000-0000-0000-000000000001')->>'version', true);
select lives_ok($$select teacher_workspace_save('aaaaaaaa-0000-0000-0000-000000000001',current_setting('test.workspace_version'),'[{"table":"classes","op":"insert","row":{"id":"aaaaaaaa-1000-0000-0000-000000000099","name":"9Ա","sort_order":3}}]')$$, 'admin saves a new class');
select is((select name from classes where id='aaaaaaaa-1000-0000-0000-000000000099'), '9Ա', 'change persisted');
select throws_ok($$select teacher_workspace_save('aaaaaaaa-0000-0000-0000-000000000001',current_setting('test.workspace_version'),'[]')$$,'40001','workspace_conflict','stale version rejected');
select set_config('test.workspace_version', teacher_workspace_read('aaaaaaaa-0000-0000-0000-000000000001')->>'version', true);
select throws_ok($$select teacher_workspace_save('aaaaaaaa-0000-0000-0000-000000000001',current_setting('test.workspace_version'),'[{"table":"classes","op":"update","row":{"id":"aaaaaaaa-1000-0000-0000-000000000099","name":"9Բ","sort_order":3}},{"table":"subjects","op":"insert","row":{"id":"aaaaaaaa-3000-0000-0000-000000000099","name":"Invalid","color":"bad"}}]')$$,'23514',null,'invalid second operation fails transaction');
select is((select name from classes where id='aaaaaaaa-1000-0000-0000-000000000099'), '9Ա', 'first operation rolled back');
select throws_ok($$select teacher_workspace_save('aaaaaaaa-0000-0000-0000-000000000001',current_setting('test.workspace_version'),'[{"table":"classes","op":"update","row":{"id":"bbbbbbbb-1000-0000-0000-000000000001","name":"Attack","sort_order":1}}]')$$,'42501',null,'cross-school row ID rejected');
select throws_ok($$select teacher_workspace_save('aaaaaaaa-0000-0000-0000-000000000001',current_setting('test.workspace_version'),'[{"table":"school_members","op":"insert","row":{}}]')$$,'22023',null,'membership table not writable through RPC');
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000002', true);
select lives_ok($$select teacher_workspace_save('aaaaaaaa-0000-0000-0000-000000000001',current_setting('test.workspace_version'),'[{"table":"classes","op":"update","row":{"id":"aaaaaaaa-1000-0000-0000-000000000099","name":"9Բ","sort_order":3}}]')$$,'scheduler can edit classes');
select set_config('test.workspace_version', teacher_workspace_read('aaaaaaaa-0000-0000-0000-000000000001')->>'version', true);
select throws_ok($$select teacher_workspace_save('aaaaaaaa-0000-0000-0000-000000000001',current_setting('test.workspace_version'),'[{"table":"schools","op":"update","row":{"id":"aaaaaaaa-0000-0000-0000-000000000001","name":"Attack","timezone":"Asia/Yerevan"}}]')$$,'42501',null,'scheduler cannot update school settings');
select lives_ok($$select teacher_workspace_save('aaaaaaaa-0000-0000-0000-000000000001',current_setting('test.workspace_version'),'[{"table":"time_slots","op":"insert","row":{"id":"aaaaaaaa-2000-0000-0000-000000000099","start_time":"16:00","end_time":"16:45","sort_order":3}}]')$$,'scheduler creates time slots');
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000004', true);
select is(teacher_workspace_read('aaaaaaaa-0000-0000-0000-000000000001'),null::jsonb,'nonmember cannot load workspace');
select throws_ok($$select teacher_workspace_save('aaaaaaaa-0000-0000-0000-000000000001',current_setting('test.workspace_version'),'[]')$$,'42501',null,'nonmember cannot save');
reset role;
set local role anon;
select throws_ok($$select teacher_workspace_read('aaaaaaaa-0000-0000-0000-000000000001')$$,'42501',null,'anonymous read denied');
select throws_ok($$select teacher_workspace_save('aaaaaaaa-0000-0000-0000-000000000001','x','[]')$$,'42501',null,'anonymous save denied');
reset role;
select * from finish();
rollback;
